\subsection{Definitions and mathematical statement}
\paragraph{Shared notation.}$\mathbb N$, $\mathbb Z$, $\mathbb Q$, $\mathbb R$, and $\mathbb C$ denote the natural numbers, integers, rationals, reals, and complex numbers, respectively. All additional parameters and hypotheses are specified in the question.


\paragraph{Statement recorded in the supplied source.}
Let $E\subset\mathbb R^n$, and let $D$ be the set of directions in which $E$ contains a unit line segment. If $D\neq\varnothing$, must $\dim_{\mathrm H}E\geq\dim_{\mathrm H}D+1$?
\par\smallskip\textit{Formulation references:} \href{https://huggingface.co/datasets/ulamai/UnsolvedMath}{[S1]}, \href{https://doi.org/10.4171/owr/2023/25}{[S2]}.

\subsection{Short English statement}
Let $E\subset\mathbb R^n$, and let $D$ be the set of directions in which $E$ contains a unit line segment. If $D\neq\varnothing$, must $\dim_{\mathrm H}E\geq\dim_{\mathrm H}D+1$?

\subsection{Sources}
\begin{itemize}
\item[S1] ULAM.AI and the UnsolvedMath Contributors, UnsolvedMath: A Curated Collection of Open Mathematics Problems, record 30005545 (OWR-13750336-006). Catalogue attribution under CC BY 4.0.
\url{https://huggingface.co/datasets/ulamai/UnsolvedMath}.
